import{_ as t,o as d,c as r,a5 as a}from"./chunks/framework.CslsFoWx.js";const h=JSON.parse('{"title":"Environnements et accès","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/acces.md","filePath":"generated/architecture/acces.md","lastUpdated":null}'),o={name:"architecture/acces.md"};function s(n,e,i,c,l,p){return d(),r("div",null,[...e[0]||(e[0]=[a('<div><h1 id="environnements-et-acces" tabindex="-1">Environnements et accès <a class="header-anchor" href="#environnements-et-acces" aria-label="Permalink to &quot;Environnements et accès&quot;">​</a></h1><p>Toutes les adresses de Vendora par environnement, au même endroit. <strong>Aucun secret ici</strong> : mots de passe, clés et jetons restent dans le gestionnaire de mots de passe et dans <code>~/.config/vendora/</code> (Mac de l&#39;équipe), jamais dans le dépôt ni dans un ticket. Détail technique : <a href="/VendoraSystem-docs/architecture/environnements">deploy/README.md</a> · variables : <a href="/VendoraSystem-docs/architecture/mise-en-production">PRODUCTION.md</a>.</p><h2 id="vue-d-ensemble" tabindex="-1">Vue d&#39;ensemble <a class="header-anchor" href="#vue-d-ensemble" aria-label="Permalink to &quot;Vue d&#39;ensemble&quot;">​</a></h2><p>Depuis le 19/11/2026 (projet Linear P-VEN-8), le <strong>staging tourne sur le Mac d&#39;Ahmed</strong> et il est publié par un tunnel ngrok : Render ne construit plus rien (minutes de build épuisées le 18/11) et GitHub Actions est payant sur le dépôt privé. L&#39;ancien « pré-staging » et le staging Render + Neon sont remplacés par cet unique environnement.</p><table tabindex="0"><thead><tr><th></th><th><strong>Dev</strong> (Mac)</th><th><strong>Staging</strong> (Mac + tunnel ngrok)</th><th><strong>Production</strong></th></tr></thead><tbody><tr><td>Rôle</td><td>Développement, tests, captures</td><td>Recette, démos, vrais appareils depuis n&#39;importe quel réseau, apps « POS Staging »</td><td>Clients (à venir)</td></tr><tr><td>Adresse</td><td>—</td><td><strong>une seule</strong>, fixe : celle du compte ngrok (<code>scripts/staging.sh urls</code>)</td><td>à définir</td></tr><tr><td>Back-office</td><td><a href="http://localhost:4200" target="_blank" rel="noreferrer">http://localhost:4200</a></td><td><code>&lt;adresse&gt;/</code></td><td>à définir</td></tr><tr><td>Console Vendora</td><td><a href="http://localhost:4300" target="_blank" rel="noreferrer">http://localhost:4300</a></td><td><code>&lt;adresse&gt;/console/</code></td><td>à définir</td></tr><tr><td>API (serveur)</td><td><a href="http://localhost:8080" target="_blank" rel="noreferrer">http://localhost:8080</a></td><td><code>&lt;adresse&gt;/api/</code></td><td>à définir</td></tr><tr><td>Assistant IA (MCP)</td><td>—</td><td><code>&lt;adresse&gt;/mcp</code> (connexion OAuth ; sonde <code>&lt;adresse&gt;/healthz/mcp</code>)</td><td>à définir</td></tr><tr><td>Santé</td><td><a href="http://localhost:8080/api/v1/public/environment" target="_blank" rel="noreferrer">http://localhost:8080/api/v1/public/environment</a></td><td><code>&lt;adresse&gt;/api/v1/public/environment</code></td><td>—</td></tr><tr><td>OpenAPI (API publique)</td><td><a href="http://localhost:8080/v3/api-docs/public" target="_blank" rel="noreferrer">http://localhost:8080/v3/api-docs/public</a></td><td><code>&lt;adresse&gt;/v3/api-docs/public</code></td><td>—</td></tr><tr><td>Sur le Mac, sans tunnel</td><td>—</td><td><a href="http://localhost:8091" target="_blank" rel="noreferrer">http://localhost:8091</a></td><td>—</td></tr><tr><td>Base de données</td><td>Postgres Docker (<code>docker compose up -d</code>)</td><td>Postgres Docker dédié (volume <code>vendora-staging-local_pgdata</code>), sauvegarde chaque nuit</td><td>à définir</td></tr><tr><td>Emails</td><td>MOCK (texte complet au journal)</td><td>MOCK (<code>scripts/staging.sh logs server</code>)</td><td>à choisir</td></tr><tr><td>Paiements, e-reporting, messages</td><td>simulés</td><td>simulés</td><td>réels</td></tr><tr><td>Images Docker</td><td>construites localement</td><td>construites localement (<code>scripts/staging.sh update</code>)</td><td>GHCR <code>ghcr.io/ahmedchebbidev/vendora-server</code> / <code>vendora-web</code>, version épinglée (<code>VENDORA_VERSION</code>), publiées par <code>scripts/build-images.sh --push</code></td></tr><tr><td>Démarrer</td><td><code>docker compose up -d</code> puis <code>./gradlew :server:bootRun</code>, <code>cd web &amp;&amp; npm start</code>, <code>cd console &amp;&amp; npm start</code></td><td><code>scripts/staging.sh up</code> (automatique à l&#39;ouverture de session après <code>scripts/staging.sh install</code>)</td><td>—</td></tr><tr><td>Mettre à jour</td><td>—</td><td><code>scripts/staging.sh update</code> — <strong>un push sur <code>main</code> ne déploie plus rien</strong></td><td>—</td></tr></tbody></table><p><strong>Particularités du staging local</strong> : il ne répond que si le Mac est allumé et éveillé ; plan gratuit de ngrok = une seule adresse (d&#39;où les chemins <code>/console/</code>, <code>/mcp</code>), environ 20 000 requêtes et 1 Go sortant par mois, page d&#39;avertissement à la première visite d&#39;un navigateur. Solution de repli sans quota : <code>scripts/staging.sh up --cloudflare</code> (adresse nouvelle à chaque démarrage). Détail : <a href="/VendoraSystem-docs/architecture/environnements">deploy/README.md §7</a>.</p><p><strong>Fonctions allumées au staging</strong> (reprises de l&#39;ancien staging Render, dans <code>deploy/docker-compose.staging-local.yml</code>) : connexion OAuth des assistants avec en-tête de ressource exigé ; propositions de l&#39;assistant (<code>POS_AGENT_PROPOSALS_ENABLED</code>, VEN-34, accord d&#39;Ahmed du 15/11/2026) ; types <code>PURCHASE_ORDER,PRICE_CHANGE,FRAUD_ALERT_HANDLING,PRODUCT_AVAILABILITY</code> (VEN-54, accord du 18/11/2026) ; limites de débit de l&#39;inscription. La production reste éteinte.</p><p><strong>Ré-appairage</strong> : l&#39;adresse du staging a changé le 19/11/2026. Un appareil appairé à l&#39;ancien staging Render doit être appairé de nouveau (Back-office › Appareils › Ajouter un appareil), et un assistant connecté par OAuth doit être reconnecté à <code>&lt;adresse&gt;/mcp</code>. La base est neuve : seuls les commerces fictifs de <code>scripts/staging.sh seed</code> existent.</p><p><strong>Ancien staging Render + Neon</strong> : à l&#39;arrêt depuis le 18/11/2026 (dernier commit déployé : <code>0d1d842a</code> du 16/11). Les services sont suspendus puis supprimés avec l&#39;accord d&#39;Ahmed (VEN-104).</p><h2 id="applications-mobiles" tabindex="-1">Applications mobiles <a class="header-anchor" href="#applications-mobiles" aria-label="Permalink to &quot;Applications mobiles&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Dev</th><th>Staging</th><th>Production</th></tr></thead><tbody><tr><td>Android</td><td><code>pos.android</code> (Debug)</td><td>« POS Staging » <code>pos.android.staging</code></td><td><code>pos.android</code> (Release)</td></tr><tr><td>iOS (iPhone, iPad)</td><td><code>tn.pos.app</code> (Debug)</td><td>« POS Staging » <code>tn.pos.app.staging</code> (schéma <code>PosApp Staging</code>)</td><td><code>tn.pos.app</code> (Release)</td></tr><tr><td>Serveur par défaut</td><td>adresse du Mac</td><td>adresse ngrok du staging local (VEN-101 ; en attendant : la saisir ou scanner le QR d&#39;appairage)</td><td>à définir</td></tr><tr><td>Appairage</td><td>Back-office › Appareils › Ajouter un appareil (code ou QR)</td><td>idem sur le back-office de staging</td><td>idem</td></tr></tbody></table><h2 id="sites-publics" tabindex="-1">Sites publics <a class="header-anchor" href="#sites-publics" aria-label="Permalink to &quot;Sites publics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Site</th><th>Adresse</th><th>Mise à jour</th></tr></thead><tbody><tr><td>Centre d&#39;aide (clients)</td><td><a href="https://ahmedchebbidev.github.io/VendoraSystem-docs/aide/" target="_blank" rel="noreferrer">https://ahmedchebbidev.github.io/VendoraSystem-docs/aide/</a></td><td><code>help/scripts/publish.sh</code> (GitHub Pages, dossier <code>aide/</code> du dépôt du site ; depuis le 19/11/2026)</td></tr><tr><td>Documentation (produit, technique, suivi)</td><td><a href="https://ahmedchebbidev.github.io/VendoraSystem-docs/" target="_blank" rel="noreferrer">https://ahmedchebbidev.github.io/VendoraSystem-docs/</a></td><td><code>site/scripts/publish.sh</code></td></tr><tr><td>Présentation, tarifs, devis</td><td><a href="https://ahmedchebbidev.github.io/VendoraSystem-docs/vendora/" target="_blank" rel="noreferrer">https://ahmedchebbidev.github.io/VendoraSystem-docs/vendora/</a></td><td>idem</td></tr><tr><td>Suivi des tâches</td><td><a href="https://linear.app/vendorasystem/team/VEN" target="_blank" rel="noreferrer">Linear, équipe « VendoraSystem »</a> (document « Environnements et accès »)</td><td>en continu</td></tr></tbody></table><h2 id="tableaux-de-bord-des-hebergeurs" tabindex="-1">Tableaux de bord des hébergeurs <a class="header-anchor" href="#tableaux-de-bord-des-hebergeurs" aria-label="Permalink to &quot;Tableaux de bord des hébergeurs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Service</th><th>Où</th><th>Accès</th></tr></thead><tbody><tr><td>ngrok (tunnel du staging local : adresse fixe, quota du mois)</td><td>dashboard.ngrok.com</td><td>compte d&#39;Ahmed ; jeton dans <code>deploy/env/staging-local.env</code> (ignoré par git)</td></tr><tr><td>Render et Neon (ancien staging, à l&#39;arrêt)</td><td>dashboard.render.com · console.neon.tech</td><td>compte d&#39;Ahmed ; à supprimer (VEN-104)</td></tr><tr><td>Brevo (emails, non branché sur le staging local)</td><td>app.brevo.com</td><td>compte d&#39;Ahmed</td></tr><tr><td>GitHub (code, site de doc, centre d&#39;aide ; Actions désactivé)</td><td>github.com/ahmedchebbidev</td><td>compte d&#39;Ahmed</td></tr><tr><td>GitHub Container Registry (images <code>vendora-server</code>, <code>vendora-web</code>)</td><td>github.com/ahmedchebbidev?tab=packages</td><td>publié à la main par <code>scripts/build-images.sh --push</code> (plus de CI GitHub depuis le 19/11/2026) ; tirer : <code>docker login ghcr.io</code> avec un jeton <code>read:packages</code> par machine (<code>~/.config/vendora/ghcr-read-token</code>, jamais dans le dépôt) — <a href="/VendoraSystem-docs/architecture/environnements">deploy/README.md §9</a></td></tr></tbody></table><h2 id="comptes-de-demo" tabindex="-1">Comptes de démo <a class="header-anchor" href="#comptes-de-demo" aria-label="Permalink to &quot;Comptes de démo&quot;">​</a></h2><p>Uniquement des commerces <strong>fictifs</strong> (« Le Petit Bistrot (démo) », « Épicerie Lumière (démo) »), adresses <code>…@vendora.test</code> créées par <code>help/tools/seed/seed-demo.py</code>. Leurs mots de passe ne sont pas versionnés. Ne jamais utiliser le nom ni les données d&#39;un vrai commerce dans une capture, un ticket ou une démo publique.</p></div>',1)])])}const m=t(o,[["render",s]]);export{h as __pageData,m as default};
